\connect f14_synthetic
DO $$ BEGIN IF current_database()<>'f14_synthetic' OR current_user<>'postgres' THEN RAISE EXCEPTION 'Disposable only';END IF;END $$;
CREATE SCHEMA f18_test;
CREATE FUNCTION f18_test.check(p_name text,p_ok boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF p_ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL %',p_name;END IF;RAISE NOTICE 'PASS F18 %',p_name;END $$;
CREATE FUNCTION f18_test.owner(n int) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$ SELECT ('82000000-0000-4000-8000-'||lpad(to_hex(n),12,'0'))::uuid $$;
CREATE FUNCTION f18_test.login(n int) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM set_config('request.jwt.claim.sub',f18_test.owner(n)::text,false);PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',f18_test.owner(n))::text,false);END $$;
SELECT f18_test.check('INSTALL_CHECKOUT_AND_PROMO_OFF',(SELECT NOT checkouts_enabled AND NOT invitations_enabled AND NOT hosted_certified FROM supporter_private.public_supporter_control));
SELECT f18_test.check('LEGACY_CREATE_PATH_CLOSED',NOT admin_private.pazo_live_control_admits(f18_test.owner(2),1));
SELECT f18_test.check('TABLES_PRIVATE',NOT has_table_privilege('authenticated','supporter_private.supporter_promotion','SELECT') AND NOT has_table_privilege('service_role','supporter_private.public_supporter_control','UPDATE'));
SELECT f18_test.check('RLS_FORCED',(SELECT bool_and(relrowsecurity AND relforcerowsecurity) FROM pg_class WHERE oid IN('supporter_private.supporter_promotion'::regclass,'supporter_private.supporter_engagement'::regclass,'supporter_private.supporter_payment_notice'::regclass,'supporter_private.public_supporter_control'::regclass,'admin_private.public_supporter_audit'::regclass)));
SELECT f18_test.check('PRIVATE_SERVICE_RPC',NOT has_function_privilege('authenticated','public.pazo_f18_supporter_tick(boolean,boolean)','EXECUTE') AND NOT has_function_privilege('authenticated','public.pazo_f18_supporter_admin_action(uuid,text,bigint,uuid)','EXECUTE'));
SELECT f18_test.check('LEGACY_COMMERCIAL_RPC_RETIRED',NOT has_function_privilege('authenticated','public.pazo_gradual_interest(text)','EXECUTE') AND NOT has_function_privilege('service_role','public.pazo_f16_gradual_tick(boolean,boolean)','EXECUTE'));
INSERT INTO auth.users(id,email_confirmed_at,is_anonymous,created_at) SELECT f18_test.owner(n),clock_timestamp(),false,clock_timestamp() FROM generate_series(101,180)n;
INSERT INTO public.profiles SELECT f18_test.owner(n),true FROM generate_series(101,180)n;
INSERT INTO public.pets(id,owner_id,name) SELECT f18_test.owner(n),f18_test.owner(n),'Synthetic' FROM generate_series(101,180)n;
