INSERT INTO supporter_private.supporter_engagement(owner_id,first_use_at,returned_at,meaningful_at) VALUES(f18_test.owner(110),now()-interval '2 days',now(),now());
DO $$ DECLARE original uuid;fresh uuid;BEGIN
 original:=(public.pazo_supporter_promotion('claim')->>'token')::uuid;
 UPDATE supporter_private.supporter_promotion SET render_expires_at=now()-interval '1 second' WHERE owner_id=f18_test.owner(110);
 fresh:=(public.pazo_supporter_promotion('claim')->>'token')::uuid;
 PERFORM f18_test.check('UNSHOWN_EXPIRED_LEASE_RECOVERABLE',fresh IS NOT NULL AND fresh<>original);
 PERFORM f18_test.check('EXPIRED_DEVICE_CANNOT_DISPLAY',public.pazo_supporter_promotion('display',original)->>'show'='false');
 PERFORM f18_test.check('FRESH_DEVICE_CAN_COMMIT',public.pazo_supporter_promotion('display',fresh)->>'show'='true');
END $$;
